#include <nuttx/config.h>
#include <nuttx/event.h>
#include <nuttx/semaphore.h>
#include <errno.h>

#ifdef CONFIG_SCHED_EVENTS

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: nxevent_init
 *
 * Description:
 *   Initialize an event group object
 *
 * Input Parameters:
 *   event - pointer to event group object
 *
 * Returned Value:
 *   Returns 0 (OK) on success or a negated errno value on failure
 *
 ****************************************************************************/

int nxevent_init(nxevent_t *event)
{
  int ret;

  if (event == NULL)
    {
      return -EINVAL;
    }

  /* Initialize the event bits to zero */
  event->ev_bits = 0;

  /* Initialize the semaphore */
  ret = sem_init(&event->ev_sem, 0, 1);
  if (ret < 0)
    {
      return ret;
    }

  return OK;
}

#endif /* CONFIG_SCHED_EVENTS */
EOF"}

