#include <nuttx/config.h>
#include <nuttx/event.h>
#include <nuttx/semaphore.h>
#include <errno.h>

#ifdef CONFIG_SCHED_EVENTS

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: nxevent_post
 *
 * Description:
 *   Post events to an event group
 *
 * Input Parameters:
 *   event - pointer to event group object
 *   bits  - event bits to post
 *   flags - operation flags (currently unused)
 *
 * Returned Value:
 *   Returns 0 (OK) on success or a negated errno value on failure
 *
 ****************************************************************************/

int nxevent_post(nxevent_t *event, uint32_t bits, int flags)
{
  int ret;

  if (event == NULL)
    {
      return -EINVAL;
    }

  /* Take the semaphore */
  ret = sem_wait(&event->sem);
  if (ret < 0)
    {
      return -errno;
    }

  /* Set the event bits */
  event->events |= bits;

  /* Release the semaphore */
  sem_post(&event->sem);

  return OK;
}

#endif /* CONFIG_SCHED_EVENTS */
EOF"}

