/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>
#include <nuttx/event.h>
#include <nuttx/semaphore.h>
#include <nuttx/clock.h>
#include <errno.h>

#ifdef CONFIG_SCHED_EVENTS

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: nxevent_do_wait
 *
 * Description:
 *   Internal function to perform event waiting
 *
 ****************************************************************************/

static int nxevent_do_wait(nxevent_t *event, uint32_t bits, int flags,
                           bool timed, unsigned int timeout)
{
  int ret;
  uint32_t result;
  struct timespec abstime;

  /* Take the semaphore */
  if (timed && timeout != 0)
    {
      /* Convert timeout to absolute time */
      clock_gettime(CLOCK_REALTIME, &abstime);
      abstime.tv_sec += timeout / TICK_PER_SEC;
      abstime.tv_nsec += (timeout % TICK_PER_SEC) * NSEC_PER_TICK;
      if (abstime.tv_nsec >= NSEC_PER_SEC)
        {
          abstime.tv_sec++;
          abstime.tv_nsec -= NSEC_PER_SEC;
        }

      ret = nxsem_timedwait(&event->sem, &abstime);
    }
  else if (!timed && timeout == 0)
    {
      ret = nxsem_trywait(&event->sem);
    }
  else
    {
      ret = nxsem_wait(&event->sem);
    }

  if (ret < 0)
    {
      return ret;
    }

  /* Check if the requested bits are available */
  if (flags & NXEVENT_WAIT_ALL)
    {
      result = (event->events & bits) == bits ? bits : 0;
    }
  else
    {
      result = event->events & bits;
    }

  /* If we have what we're waiting for, return it */
  if (result != 0)
    {
      /* Release the semaphore */
      nxsem_post(&event->sem);
      return result;
    }

  /* For trywait, don't block */
  if (!timed && timeout == 0)
    {
      nxsem_post(&event->sem);
      return -EAGAIN;
    }

  /* Release the semaphore */
  nxsem_post(&event->sem);

  /* For now, we'll just return ETIMEDOUT for timed operations that don't find events */
  /* A full implementation would need a wait queue */
  if (timed && timeout != 0)
    {
      return -ETIMEDOUT;
    }

  /* For infinite wait, this is a simplified implementation */
  /* A real implementation would use a wait queue */
  return -ETIMEDOUT;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: nxevent_wait
 *
 * Description:
 *   Wait for events from an event group
 *
 * Input Parameters:
 *   event   - pointer to event group object
 *   bits    - event bits to wait for
 *   flags   - wait flags (NXEVENT_WAIT_ANY or NXEVENT_WAIT_ALL)
 *
 * Returned Value:
 *   Returns the event bits that were available or a negated errno value on failure
 *
 ****************************************************************************/

int nxevent_wait(nxevent_t *event, uint32_t bits, int flags)
{
  if (event == NULL || bits == 0)
    {
      return -EINVAL;
    }

  return nxevent_do_wait(event, bits, flags, false, 0);
}

/****************************************************************************
 * Name: nxevent_tickwait
 *
 * Description:
 *   Wait for events from an event group with timeout in ticks
 *
 * Input Parameters:
 *   event   - pointer to event group object
 *   bits    - event bits to wait for
 *   flags   - wait flags (NXEVENT_WAIT_ANY or NXEVENT_WAIT_ALL)
 *   timeout - timeout in system ticks
 *
 * Returned Value:
 *   Returns the event bits that were available or a negated errno value on failure
 *
 ****************************************************************************/

int nxevent_tickwait(nxevent_t *event, uint32_t bits, int flags,
                     unsigned int timeout)
{
  if (event == NULL || bits == 0)
    {
      return -EINVAL;
    }

  return nxevent_do_wait(event, bits, flags, true, timeout);
}

/****************************************************************************
 * Name: nxevent_trywait
 *
 * Description:
 *   Try to wait for events from an event group without blocking
 *
 * Input Parameters:
 *   event   - pointer to event group object
 *   bits    - event bits to wait for
 *   flags   - wait flags (NXEVENT_WAIT_ANY or NXEVENT_WAIT_ALL)
 *
 * Returned Value:
 *   Returns the event bits that were available or a negated errno value on failure
 *
 ****************************************************************************/

int nxevent_trywait(nxevent_t *event, uint32_t bits, int flags)
{
  if (event == NULL || bits == 0)
    {
      return -EINVAL;
    }

  return nxevent_do_wait(event, bits, flags, true, 0);
}

#endif /* CONFIG_SCHED_EVENTS */
