#include <nuttx/event.h>
#include <nuttx/semaphore.h>
#include <errno.h>

#ifdef CONFIG_SCHED_EVENTS

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: nxevent_reset
 *
 * Description:
 *   Reset events in an event group
 *
 * Input Parameters:
 *   event - pointer to event group object
 *   bits  - event bits to reset
 *
 * Returned Value:
 *   Returns 0 (OK) on success or a negated errno value on failure
 *
 ****************************************************************************/

int nxevent_reset(nxevent_t *event, uint32_t bits)
{
  int ret;

  if (event == NULL)
    {
      return -EINVAL;
    }

  /* Take the semaphore */
  ret = nxsem_wait(&event->sem);
  if (ret < 0)
    {
      return ret;
    }

  /* Clear the specified event bits */
  event->events &= ~bits;

  /* Release the semaphore */
  nxsem_post(&event->sem);

  return OK;
}

#endif /* CONFIG_SCHED_EVENTS */
